using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Academy.Api.Auth;
using Academy.Api.Slice4;
using Academy.Api.Slice5;
using Academy.Infrastructure.Evaluations;
using Academy.Infrastructure.Persistence;
using Academy.Infrastructure.Tenancy;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
namespace Academy.IntegrationTests;
public sealed partial class BrandingMatchesTests
{
    private const string Badges="/api/v1/evaluations/badges";
    private static BadgeRuleWrite BadgeRule(Guid sport,int points=10)=>new(sport,"مجهود ملاحظ اصطناعي "+Guid.NewGuid().ToString("N")[..6],"مراجعة بشرية لتحسن التعاون والمحاولة دون ترتيب أو عقوبة أو مال",points,true,Guid.NewGuid());
    [Fact]public async Task Badge_coach_current_assignment_is_required_again_before_replay()
    {
        using var owner=await Staff();using var coach=await Mobile(AcademyRole.Coach);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var opts=await coach.GetFromJsonAsync<JsonElement>("/api/v1/evaluations/options");var id=opts.GetProperty("enrollments")[0].GetProperty("id").GetGuid();var source=await db.SportEnrollments.AsNoTracking().SingleAsync(e=>e.Id==id);var e=await FreshSkillChild(db,source);var rule=await LessonId(await Send(owner,Badges+"/rules",BadgeRule(e.SportId)));var url=$"{Badges}/enrollments/{e.Id}";var d=(await coach.GetFromJsonAsync<JsonElement>(url)).GetProperty("enrollments")[0];var b=new BadgeGrantWrite(rule,d.GetProperty("enrollmentVersion").GetUInt32(),DateOnly.Parse(d.GetProperty("asOfDate").GetString()!),null,Guid.NewGuid());var grant=await LessonId(await Send(coach,url+"/grant",b));d=(await coach.GetFromJsonAsync<JsonElement>(url)).GetProperty("enrollments")[0];var revoke=new BadgeActionWrite(d.GetProperty("items")[0].GetProperty("version").GetUInt32(),null,Guid.NewGuid());var hash=Academy.Api.Mobile.MobileAuthenticationHandler.Hash(coach.DefaultRequestHeaders.Authorization!.Parameter!);var member=await db.MobileSessions.Where(s=>s.AccessTokenHash==hash).Select(s=>s.MembershipId).SingleAsync();var a=await db.StaffGroupAssignments.SingleAsync(a=>a.TrainingGroupId==e.TrainingGroupId&&a.AcademyMembershipId==member&&a.IsActive);
        try{a.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await coach.GetAsync(url)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(coach,url+"/grant",b)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(coach,$"{Badges}/grants/{grant}/revoke",revoke)).StatusCode);Assert.False(await db.PlayerBadgeRevocations.AnyAsync(v=>v.GrantId==grant));}finally{a.IsActive=true;await db.SaveChangesAsync();}
    }
    [Fact]public async Task Badge_scoped_admin_requires_separate_read_add_edit_and_scope_before_replay()=>await DelegateFixture(async(owner,admin,db,group,member)=>{
        var e=await FreshSkillChild(db,new(){AcademyId=group.AcademyId,SportId=group.SportId,BranchId=group.BranchId,TrainingGroupId=group.Id});var rule=await LessonId(await Send(owner,Badges+"/rules",BadgeRule(group.SportId)));var access=await db.StaffActionGrants.SingleOrDefaultAsync(g=>g.MembershipId==member&&g.Module=="evaluations");var old=access==null?null:JsonSerializer.Serialize(access);access??=new(){Id=Guid.NewGuid(),AcademyId=group.AcademyId,MembershipId=member,Module="evaluations"};if(old==null)db.StaffActionGrants.Add(access);
        try{access.Read=true;access.IsActive=true;access.Add=false;access.Edit=true;await db.SaveChangesAsync();var url=$"{Badges}/enrollments/{e.Id}";var d=(await admin.GetFromJsonAsync<JsonElement>(url)).GetProperty("enrollments")[0];var b=new BadgeGrantWrite(rule,d.GetProperty("enrollmentVersion").GetUInt32(),DateOnly.Parse(d.GetProperty("asOfDate").GetString()!),null,Guid.NewGuid());Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,url+"/grant",b)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,Badges+"/rules",BadgeRule(group.SportId))).StatusCode);access.Add=true;access.Edit=false;await db.SaveChangesAsync();var g=await LessonId(await Send(admin,url+"/grant",b));d=(await admin.GetFromJsonAsync<JsonElement>(url)).GetProperty("enrollments")[0];var revoke=new BadgeActionWrite(d.GetProperty("items")[0].GetProperty("version").GetUInt32(),null,Guid.NewGuid());Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,$"{Badges}/grants/{g}/revoke",revoke)).StatusCode);access.Add=false;access.Edit=true;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,url+"/grant",b)).StatusCode);await LessonId(await Send(admin,$"{Badges}/grants/{g}/revoke",revoke));access.Edit=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,$"{Badges}/grants/{g}/revoke",revoke)).StatusCode);access.Add=true;access.Edit=true;await db.SaveChangesAsync();var branch=await db.MembershipBranchAccesses.SingleAsync(s=>s.MembershipId==member&&s.BranchId==group.BranchId);branch.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await admin.GetAsync(url)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(admin,url+"/grant",b)).StatusCode);branch.IsActive=true;await db.SaveChangesAsync();var sport=await db.MembershipSportAccesses.SingleAsync(s=>s.MembershipId==member&&s.SportId==group.SportId);sport.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await admin.GetAsync(url)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(admin,$"{Badges}/grants/{g}/revoke",revoke)).StatusCode);sport.IsActive=true;access.Read=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await admin.GetAsync(url)).StatusCode);}
        finally{if(old==null)db.StaffActionGrants.Remove(access);else db.Entry(access).CurrentValues.SetValues(JsonSerializer.Deserialize<StaffActionGrant>(old)!);await db.SaveChangesAsync();}
    });
    [Fact]public async Task Badge_explicit_rule_grant_retirement_and_revocation_preserve_evidence_and_same_sport_summary_without_money_or_promotion()
    {
        using var owner=await Staff();using var coach=await Mobile(AcademyRole.Coach);using var family=await Mobile(AcademyRole.Guardian);using var foreign=await Staff(DemoSeed.FutureOwnerEmail);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var options=await coach.GetFromJsonAsync<JsonElement>("/api/v1/evaluations/options");var eid=options.GetProperty("enrollments")[0].GetProperty("id").GetGuid();var source=await db.SportEnrollments.AsNoTracking().SingleAsync(e=>e.Id==eid);var guardian=await db.GuardianProfiles.Where(g=>g.User.PhoneNumber==DemoSeed.GuardianPhone&&g.AcademyId==source.AcademyId).Select(g=>g.Id).SingleAsync();var e=await FreshSkillChild(db,source,guardian);var url=$"{Badges}/enrollments/{e.Id}";var d=(await owner.GetFromJsonAsync<JsonElement>(url)).GetProperty("enrollments")[0];var today=DateOnly.Parse(d.GetProperty("asOfDate").GetString()!);var money=await owner.GetStringAsync("/api/v1/reports/financial?from=2026-09-01&to=2026-09-28");var periods=await db.SubscriptionPeriods.CountAsync();var attendance=await db.PlayerAttendances.CountAsync();var transfers=await db.EnrollmentGroupTransfers.CountAsync();var notices=await db.AcademyNotices.CountAsync();var levels=await db.PlayerLevelReviews.CountAsync();
        var ruleBody=BadgeRule(e.SportId);Assert.Equal(HttpStatusCode.BadRequest,(await owner.PostAsJsonAsync(Badges+"/rules",ruleBody)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await Send(coach,Badges+"/rules",ruleBody)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await Send(family,Badges+"/rules",ruleBody)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(foreign,Badges+"/rules",ruleBody)).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await Send(owner,Badges+"/rules",ruleBody with{Points=-1})).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await Send(owner,Badges+"/rules",ruleBody with{ConfirmPublication=false})).StatusCode);
        var r=await LessonId(await Send(owner,Badges+"/rules",ruleBody));Assert.Equal(r,await LessonId(await Send(owner,Badges+"/rules",ruleBody)));Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,Badges+"/rules",ruleBody with{Points=30})).StatusCode);var r2=await LessonId(await Send(owner,Badges+"/rules",BadgeRule(e.SportId,20)));var b=new BadgeGrantWrite(r,d.GetProperty("enrollmentVersion").GetUInt32(),today,null,Guid.NewGuid());
        Assert.Equal(HttpStatusCode.BadRequest,(await owner.PostAsJsonAsync(url+"/grant",b)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await Send(family,url+"/grant",b)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(foreign,url+"/grant",b)).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await Send(coach,url+"/grant",b with{EnrollmentVersion=b.EnrollmentVersion+1})).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await Send(coach,url+"/grant",b with{ObservedOn=today.AddDays(1)})).StatusCode);var wrongSport=await db.Sports.Where(s=>s.AcademyId==e.AcademyId&&s.IsActive&&s.Id!=e.SportId).Select(s=>s.Id).FirstAsync();var wrongRule=await LessonId(await Send(owner,Badges+"/rules",BadgeRule(wrongSport)));Assert.Equal(HttpStatusCode.NotFound,(await Send(coach,url+"/grant",b with{RuleId=wrongRule})).StatusCode);
        var g=await LessonId(await Send(coach,url+"/grant",b));Assert.Equal(g,await LessonId(await Send(coach,url+"/grant",b)));Assert.Equal(HttpStatusCode.Conflict,(await Send(coach,url+"/grant",b with{RequestId=Guid.NewGuid()})).StatusCode);await LessonId(await Send(owner,url+"/grant",b with{RuleId=r2,RequestId=Guid.NewGuid()}));
        async Task<JsonElement> Mine()=>(await family.GetFromJsonAsync<JsonElement>($"/api/v1/guardian/children/{e.PlayerId}/badges")).GetProperty("enrollments")[0];Assert.Equal(30,(await Mine()).GetProperty("points").GetInt64());Assert.Equal(2,(await Mine()).GetProperty("items").GetArrayLength());Assert.False((await Mine()).GetProperty("canGrant").GetBoolean());Assert.Equal(HttpStatusCode.NotFound,(await family.GetAsync($"/api/v1/guardian/children/{Guid.NewGuid()}/badges")).StatusCode);
        var rule=await db.PlayerBadgeRules.AsNoTracking().SingleAsync(x=>x.Id==r);var retire=new BadgeActionWrite(rule.Version,"ملاحظة إدارية غير منشورة للأسرة",Guid.NewGuid());Assert.Equal(HttpStatusCode.Forbidden,(await Send(coach,$"{Badges}/rules/{r}/retire",retire)).StatusCode);await LessonId(await Send(owner,$"{Badges}/rules/{r}/retire",retire));await LessonId(await Send(owner,$"{Badges}/rules/{r}/retire",retire));Assert.Equal(30,(await Mine()).GetProperty("points").GetInt64());Assert.DoesNotContain("ملاحظة إدارية",(await Mine()).GetRawText());var other=await FreshSkillChild(db,source,guardian);var otherVersion=await db.SportEnrollments.Where(x=>x.Id==other.Id).Select(x=>x.Version).SingleAsync();Assert.Equal(HttpStatusCode.NotFound,(await Send(owner,$"{Badges}/enrollments/{other.Id}/grant",b with{EnrollmentVersion=otherVersion,RequestId=Guid.NewGuid()})).StatusCode);
        var granted=(await owner.GetFromJsonAsync<JsonElement>(url)).GetProperty("enrollments")[0].GetProperty("items").EnumerateArray().Single(x=>x.GetProperty("id").GetGuid()==g);var revoke=new BadgeActionWrite(granted.GetProperty("version").GetUInt32(),null,Guid.NewGuid());Assert.Equal(HttpStatusCode.Forbidden,(await Send(family,$"{Badges}/grants/{g}/revoke",revoke)).StatusCode);await LessonId(await Send(coach,$"{Badges}/grants/{g}/revoke",revoke));await LessonId(await Send(coach,$"{Badges}/grants/{g}/revoke",revoke));Assert.Equal(HttpStatusCode.Conflict,(await Send(coach,$"{Badges}/grants/{g}/revoke",revoke with{Note="نفس المفتاح مختلف"})).StatusCode);Assert.Equal(20,(await Mine()).GetProperty("points").GetInt64());Assert.Equal("Revoked",(await Mine()).GetProperty("items").EnumerateArray().Single(x=>x.GetProperty("id").GetGuid()==g).GetProperty("state").GetString());Assert.Equal(g,await LessonId(await Send(coach,url+"/grant",b)));Assert.Equal(20,(await Mine()).GetProperty("points").GetInt64());
        var now=DateTimeOffset.UtcNow;db.PlayerBadgeGrants.Add(new(){Id=Guid.NewGuid(),AcademyId=e.AcademyId,RuleId=r2,SportEnrollmentId=other.Id,SportId=e.SportId,ObservedOn=today.AddDays(1),ActorUserId=rule.ActorUserId,ActorName=rule.ActorName,RequestId=Guid.NewGuid(),RequestHash="forged-future-badge",CreatedAtUtc=now,UpdatedAtUtc=now});var sql=await Assert.ThrowsAsync<DbUpdateException>(()=>db.SaveChangesAsync());Assert.Equal("23514",Assert.IsType<Npgsql.PostgresException>(sql.InnerException).SqlState);db.ChangeTracker.Clear();var row=await db.PlayerBadgeRules.SingleAsync(x=>x.Id==r);row.Points=999;await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());db.ChangeTracker.Clear();var immutable=await Assert.ThrowsAsync<Npgsql.PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM \"PlayerBadgeRevocations\" WHERE \"GrantId\"={g}"));Assert.Equal("23514",immutable.SqlState);
        var after=await db.SportEnrollments.AsNoTracking().SingleAsync(x=>x.Id==e.Id);Assert.Equal(e.TrainingLevelId,after.TrainingLevelId);Assert.Equal(e.TrainingGroupId,after.TrainingGroupId);Assert.Equal(periods,await db.SubscriptionPeriods.CountAsync());Assert.Equal(attendance,await db.PlayerAttendances.CountAsync());Assert.Equal(transfers,await db.EnrollmentGroupTransfers.CountAsync());Assert.Equal(levels,await db.PlayerLevelReviews.CountAsync());Assert.Equal(notices,await db.AcademyNotices.CountAsync());Assert.Equal(money,await owner.GetStringAsync("/api/v1/reports/financial?from=2026-09-01&to=2026-09-28"));var link=await db.GuardianPlayerLinks.SingleAsync(l=>l.PlayerId==e.PlayerId);link.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await family.GetAsync($"/api/v1/guardian/children/{e.PlayerId}/badges")).StatusCode);
    }
}
